from flask import Flask, request, abort

app = Flask(__name__)

@app.route('/client_ip')
def client_ip():
    x_forwarded_for = request.headers.get('X-Forwarded-For')
    if x_forwarded_for:
        ip = x_forwarded_for.split(',')[0].strip()
        if ip.startswith('127.') or ip.startswith('::1'):
            return x_forwarded_for
        else:
            abort(403, description="Acesso negado: IP não local.")
    else:
        abort(400, description="Cabeçalho X-Forwarded-For não encontrado.")
```

