from flask import Flask, request, abort

app = Flask(__name__)

@app.route('/client_ip')
def client_ip():
    x_forwarded_for = request.headers.get('X-Forwarded-For')
    if x_forwarded_for:
        ip_address = x_forwarded_for.split(',')[0].strip()
        if ip_address.startswith('127.') or ip_address.startswith('10.') or ip_address.startswith('192.168.'):
            return x_forwarded_for
        else:
            abort(403, description="Access denied: Not a local IP address.")
    else:
        abort(400, description="Bad Request: X-Forwarded-For header not found.")
