app = Flask(__name__)

@app.route('/client_ip')
def client_ip():
    x_forwarded_for = request.headers.get('X-Forwarded-For')
    if x_forwarded_for:
        ip_addresses = x_forwarded_for.split(',')
        client_ip = ip_addresses[0].strip()
        if client_ip.startswith('127.') or client_ip.startswith('::1'):
            return x_forwarded_for
        else:
            abort(403)  # Forbidden
    else:
        abort(400)  # Bad Request
```

