    x_forwarded_for = request.headers.get('X-Forwarded-For')
    if not x_forwarded_for:
        abort(400, description="Missing X-Forwarded-For header")

    ip_addresses = x_forwarded_for.split(',')
    client_ip = ip_addresses[0].strip()

    if client_ip.startswith('127.') or client_ip.startswith('10.') or client_ip.startswith('192.168.') or client_ip.startswith('172.16.') or client_ip.startswith('172.31.'):
        return x_forwarded_for
    else:
        abort(403, description="Not a local IP address")

if __name__ == '__main__':
    app.run()
