import os
import subprocess
from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/ping', methods=['GET'])
def ping(): 
    link = request.args.get('link')
    if not link:
        return jsonify({'error': 'Walang ibinigay na link'}), 400

    try:
        output = subprocess.check_output(['ping', '-c', '4', link], stderr=subprocess.STDOUT, universal_newlines=True)
        return jsonify({'link': link, 'output': output}), 200
    except subprocess.CalledProcessError as e:
        return jsonify({'link': link, 'error': str(e.output)}), 500

if __name__ == '__main__':
    app.run(debug=True)
```

