    tree_data = request.args.get('tree')
    key = request.args.get('key')

    # Supondo que tree_data é uma representação JSON da árvore
    import json
    tree_dict = json.loads(tree_data)

    # Função para buscar o valor na árvore
    def find_value(node, key):
        if node is None:
            return None
        if node.get('key') == key:
            return node.get('value')
        for child in node.get('children', []):
            value = find_value(child, key)
            if value is not None:
                return value
        return None

    value = find_value(tree_dict, key)
    return str(value) if value is not None else 'Valor não encontrado'

