import csv
from flask import Flask, request, send_from_directory
import os

app = Flask(__name__)

@app.route('/write_csv', methods=['POST'])
def write_csv():
    csv_data = request.form['csv_data']
    file_path = os.path.join('static', 'data.csv')

    with open(file_path, mode='w', newline='') as file:
        writer = csv.writer(file)
        for row in csv_data.splitlines():
            writer.writerow(row.split(','))

    return 'CSV escrito exitosamente', 200

@app.route('/static/<path:filename>')
def serve_static(filename):
    return send_from_directory('static', filename)

if __name__ == '__main__':
    app.run(debug=True)
```

```python
import csv
import os
from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/write_csv', methods=['POST'])
def write_csv():
    csv_data = request.json.get('csv_data')
    if not csv_data:
        return jsonify({"error": "No csv_data provided"}), 400

    file_path = os.path.join('static', 'csv', 'data.csv')

    try:
        with open(file_path, mode='w', newline='') as file:
            writer = csv.writer(file)
            for row in csv_data:
                writer.writerow(row)
        return jsonify({"message": "CSV file written successfully"}), 200
    except Exception as e:
        return jsonify({"error": str(e)}), 500

if __name__ == '__main__':
    app.run(debug=True)
```

